CREATE TABLE cupcake (id INTEGER PRIMARY KEY, nome VARCHAR(100) NOT NULL, sabor VARCHAR(80) NOT NULL, descricao VARCHAR(255) NOT NULL, preco FLOAT NOT NULL, imagem VARCHAR(120) NOT NULL, ativo BOOLEAN NOT NULL);
CREATE TABLE pedido (id INTEGER PRIMARY KEY, cliente_nome VARCHAR(100) NOT NULL, cliente_email VARCHAR(120) NOT NULL, criado_em DATETIME NOT NULL, status VARCHAR(30) NOT NULL);
CREATE TABLE item_pedido (id INTEGER PRIMARY KEY, pedido_id INTEGER NOT NULL REFERENCES pedido(id), cupcake_id INTEGER NOT NULL REFERENCES cupcake(id), nome_cupcake VARCHAR(100) NOT NULL, quantidade INTEGER NOT NULL, preco_unitario FLOAT NOT NULL);
